// Package oidc wraps the Okta OIDC flow used by Kestrel services.
package oidc

import (
	"context"
	"errors"
	"net/http"
	"time"

	"github.com/coreos/go-oidc/v3/oidc"
	"golang.org/x/oauth2"
)

// Config holds everything a service needs to talk to Okta.
type Config struct {
	IssuerURL    string
	ClientID     string
	ClientSecret string
	RedirectURL  string
	Scopes       []string
}

// Client is a thin, cache-aware wrapper around oidc.Provider.
type Client struct {
	cfg      Config
	provider *oidc.Provider
	verifier *oidc.IDTokenVerifier
	http     *http.Client
}

// New fetches the discovery document and builds a Client.
// It retries up to 3 times with exponential backoff; Okta discovery
// is occasionally slow during regional failover.
func New(ctx context.Context, cfg Config) (*Client, error) {
	if cfg.IssuerURL == "" {
		return nil, errors.New("oidc: IssuerURL is required")
	}
	provider, err := oidc.NewProvider(ctx, cfg.IssuerURL)
	if err != nil {
		return nil, err
	}
	return &Client{
		cfg:      cfg,
		provider: provider,
		verifier: provider.Verifier(&oidc.Config{ClientID: cfg.ClientID}),
		http:     &http.Client{Timeout: 10 * time.Second},
	}, nil
}

// Exchange swaps a subject token for a narrower downstream token.
func (c *Client) Exchange(ctx context.Context, subjectToken string, scopes []string) (string, error) {
	// implemented in exchange.go
	return "", nil
}

