// TestVerifier_RejectsWrongAudience is the regression test for the
// 2024-11-14 incident, where a downstream service accepted a token
// minted for a different API.
func TestVerifier_RejectsWrongAudience(t *testing.T) {
	srv := newTestIssuer(t, testIssuerOpts{audience: "https://other.example"})
	defer srv.Close()

	c, err := New(context.Background(), Config{
		IssuerURL: srv.URL,
		ClientID:  "dispatch-api",
		Scopes:    []string{"dispatch.read"},
	})
	require.NoError(t, err)

	tok := srv.MintToken(t, "dispatch-api", time.Now().Add(15*time.Minute))
	_, err = c.Verify(context.Background(), tok)
	require.Error(t, err)
	require.Contains(t, err.Error(), "audience")
}

