/**
 * EDI 214 mapping for carrier-connect.
 * Maps X12 214 shipment status segments to canonical ShipmentEvent objects.
 * Transaction set: 214 (004010)
 */

import type { ShipmentEvent, ShipmentStatus } from '../types/shipment';

const STATUS_MAP: Record<string, ShipmentStatus> = {
  X1: 'tendered',
  X2: 'accepted',
  X3: 'in_transit',
  X4: 'out_for_delivery',
  X5: 'delivered',
  X6: 'exception',
  X7: 'returned',
  AF: 'arrived_at_facility',
  D1: 'departed_facility',
};

export interface Edi214Input {
  shipmentId: string;
  scac: string;
  statusCode: string;
  eventTime: string;
  city?: string;
  state?: string;
  postalCode?: string;
  reasonCode?: string;
}

export function mapEdi214ToShipmentEvent(input: Edi214Input): ShipmentEvent {
  const status = STATUS_MAP[input.statusCode];
  if (!status) {
    throw new Error('Unsupported EDI 214 status code: ' + input.statusCode);
  }

  return {
    shipmentId: input.shipmentId,
    carrierScac: input.scac,
    status,
    occurredAt: new Date(input.eventTime).toISOString(),
    location: input.city && input.state ? { city: input.city, state: input.state } : undefined,
    reasonCode: input.reasonCode,
    source: 'edi214',
  };
}

