/**
 * Loads carrier tenant credentials from the vault.
 * Credentials are cached in memory for the process lifetime and refreshed on rotation events.
 */

import { vault } from '@kestrel/vault-client';

export interface TenantCredentials {
  clientId: string;
  clientSecret: string;
  version: number;
}

const cache = new Map<string, TenantCredentials>();

export async function loadCredentials(carrierCode: string): Promise<TenantCredentials> {
  const cached = cache.get(carrierCode);
  if (cached) return cached;

  const path = `tenants/${carrierCode}/api`;
  const secret = await vault.read(path);

  const creds: TenantCredentials = {
    clientId: secret.data.client_id,
    clientSecret: secret.data.client_secret,
    version: secret.metadata.version,
  };

  cache.set(carrierCode, creds);
  return creds;
}

export function invalidate(carrierCode: string): void {
  cache.delete(carrierCode);
}

/**
 * Certification scenarios executed for every carrier tenant.
 * Each scenario returns a pass/fail outcome plus failure details for the evidence bundle.
 */

import type { CertScenario } from './types';

export const scenarios: CertScenario[] = [
  {
    name: 'tender_accept_flow',
    run: async (ctx) => {
      const tender = await ctx.client.tender({ stops: 2 });
      const accepted = await ctx.client.awaitStatus(tender.id, 'accepted');
      return { passed: Boolean(accepted), failures: accepted ? [] : ['no accepted status'] };
    },
  },
  {
    name: 'status_event_mapping',
    run: async (ctx) => {
      const event = await ctx.client.pushStatus({ code: 'X3' });
      return { passed: event.status === 'in_transit', failures: [] };
    },
  },
  {
    name: 'invoice_roundtrip',
    run: async (ctx) => {
      const line = await ctx.client.submitInvoice({ amount: 12500, currency: 'USD' });
      return { passed: line.amountMinor === 12500, failures: [] };
    },
  },
];

import { describe, it, expect } from 'vitest';
import { mapEdi214ToShipmentEvent } from './edi214';

describe('mapEdi214ToShipmentEvent', () => {
  it('maps X5 to delivered with a location', () => {
    const event = mapEdi214ToShipmentEvent({
      shipmentId: 'PRO123456789',
      scac: 'RLMC',
      statusCode: 'X5',
      eventTime: '2025-05-04T18:22:00Z',
      city: 'Laredo',
      state: 'TX',
    });

    expect(event.status).toBe('delivered');
    expect(event.location).toEqual({ city: 'Laredo', state: 'TX' });
    expect(event.source).toBe('edi214');
  });

  it('keeps the reason code on exceptions', () => {
    const event = mapEdi214ToShipmentEvent({
      shipmentId: 'PRO987654321',
      scac: 'GRVT',
      statusCode: 'X6',
      eventTime: '2025-05-04T09:05:00Z',
      reasonCode: 'WEA',
    });

    expect(event.status).toBe('exception');
    expect(event.reasonCode).toBe('WEA');
  });

  it('throws on an unknown status code', () => {
    expect(() =>
      mapEdi214ToShipmentEvent({
        shipmentId: 'PRO000000001',
        scac: 'GRVT',
        statusCode: 'ZZ',
        eventTime: '2025-05-04T09:05:00Z',
      }),
    ).toThrow(/Unsupported EDI 214 status code/);
  });
});

import { Router } from 'express';
import { loadCredentials } from '../../tenants/loadCredentials';
import { publishEtaUpdate } from '../../eta/publish';
import { validateEtaPayload } from '../../eta/validate';

export const etaRouter = Router();

etaRouter.post('/v1/eta', async (req, res) => {
  const carrierCode = req.header('x-carrier-code');
  if (!carrierCode) {
    return res.status(400).json({ error: 'missing_carrier_code' });
  }

  const creds = await loadCredentials(carrierCode);
  if (req.header('x-client-id') !== creds.clientId) {
    return res.status(401).json({ error: 'invalid_credentials' });
  }

  const parsed = validateEtaPayload(req.body);
  if (!parsed.ok) {
    return res.status(422).json({ error: 'invalid_payload', details: parsed.errors });
  }

  await publishEtaUpdate(carrierCode, parsed.value);
  return res.status(202).json({ accepted: true });
});

