# dock_scheduler/src/constraints.py

"""Hard and soft constraints for dock-door scheduling."""

from dataclasses import dataclass
from datetime import datetime, timedelta

@dataclass(frozen=True)
class Door:
    door_id: str
    site_code: str
    door_type: str  # "dry", "reefer", "ramp"
    active: bool = True

@dataclass(frozen=True)
class Appointment:
    shipment_id: str
    site_code: str
    start: datetime
    end: datetime
    temp_controlled: bool
    door_type_required: str

def hard_constraints_ok(appt: Appointment, door: Door, roster: dict) -> bool:
    if not door.active:
        return False
    if appt.site_code != door.site_code:
        return False
    if appt.door_type_required != door.door_type:
        return False
    if roster.get("forklift_certified", 0) < 1:
        return False
    return True

def overlaps(a: Appointment, b: Appointment) -> bool:
    return a.start < b.end and b.start < a.end

import { openDatabase } from '../db/sqlite';
import { Mutation, MutationKind } from './types';

const BATCH_SIZE = 50;

export class SyncQueue {
  private db = openDatabase('driver-app.db');

  async enqueue(mutation: Mutation): Promise<void> {
    await this.db.run(
      `INSERT INTO outbox (mutation_id, stop_id, kind, payload_json, local_photo_id, created_at, attempt_count)
       VALUES (?, ?, ?, ?, ?, ?, 0)`,
      mutation.mutationId,
      mutation.stopId,
      mutation.kind,
      JSON.stringify(mutation.payload),
      mutation.localPhotoId ?? null,
      Date.now(),
    );
  }

  async nextBatch(limit = BATCH_SIZE): Promise<Mutation[]> {
    const rows = await this.db.all(
      `SELECT * FROM outbox WHERE synced_at IS NULL ORDER BY created_at ASC LIMIT ?`,
      limit,
    );
    return rows.map(rowToMutation);
  }

  async markSynced(mutationId: string, serverResult: unknown): Promise<void> {
    await this.db.run(
      `UPDATE outbox SET synced_at = ?, server_result_json = ? WHERE mutation_id = ?`,
      Date.now(),
      JSON.stringify(serverResult),
      mutationId,
    );
  }
}

function rowToMutation(row: any): Mutation {
  return {
    mutationId: row.mutation_id,
    stopId: row.stop_id,
    kind: row.kind as MutationKind,
    payload: JSON.parse(row.payload_json),
    localPhotoId: row.local_photo_id,
  };
}

import { readFile, unlink } from 'react-native-fs';
import { postBinary } from '../api/client';

const PHOTO_DIR = `${RNFS.DocumentDirectoryPath}/pod-photos`;

export async function uploadProofPhoto(
  localPhotoId: string,
  stopId: string,
  mutationId: string,
): Promise<string> {
  const path = `${PHOTO_DIR}/${localPhotoId}.jpg`;
  const base64 = await readFile(path, 'base64');

  const response = await postBinary('/photos', {
    stop_id: stopId,
    mutation_id: mutationId,
    content_type: 'image/jpeg',
    body_base64: base64,
  });

  return response.photo_id;
}

export async function deleteLocalPhoto(localPhotoId: string): Promise<void> {
  const path = `${PHOTO_DIR}/${localPhotoId}.jpg`;
  await unlink(path).catch(() => undefined);
}

// Photos are uploaded only after the parent stop mutation is accepted.
// If upload fails, the mutation stays pending and the file remains on device.

package handlers

import (
  "encoding/json"
  "net/http"
)

type SyncBatchRequest struct {
  DeviceID   string         `json:"device_id"`
  AppVersion string         `json:"app_version"`
  Mutations  []StopMutation `json:"mutations"`
}

type StopMutation struct {
  MutationID string          `json:"mutation_id"`
  StopID     string          `json:"stop_id"`
  Kind       string          `json:"kind"`
  Payload    json.RawMessage `json:"payload"`
}

func (h *Handler) SubmitSyncBatch(w http.ResponseWriter, r *http.Request) {
  var req SyncBatchRequest
  if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
    http.Error(w, "invalid json", http.StatusBadRequest)
    return
  }

  if len(req.Mutations) > 50 {
    http.Error(w, "batch too large", http.StatusUnprocessableEntity)
    return
  }

  results, err := h.syncService.ApplyBatch(r.Context(), req)
  if err != nil {
    http.Error(w, err.Error(), http.StatusInternalServerError)
    return
  }

  writeJSON(w, http.StatusAccepted, map[string]any{"results": results})
}

package tests

import (
  "testing"

  "github.com/kestrel/pod-service/internal/sync"
)

// TestDuplicateBatchIsIdempotent replays the same batch twice and asserts
// that the second pass applies nothing new.
func TestDuplicateBatchIsIdempotent(t *testing.T) {
  svc := sync.NewService(newTestStore(t))
  batch := loadFixture(t, "sync_fixtures/complete_stop_batch.json")

  first, err := svc.ApplyBatch(ctx, batch)
  if err != nil {
    t.Fatalf("first batch failed: %v", err)
  }
  for _, r := range first.Results {
    if r.Status != "applied" {
      t.Fatalf("expected applied, got %s", r.Status)
    }
  }

  second, err := svc.ApplyBatch(ctx, batch)
  if err != nil {
    t.Fatalf("replay failed: %v", err)
  }
  for _, r := range second.Results {
    if r.Status != "already_applied" {
      t.Fatalf("expected already_applied, got %s", r.Status)
    }
  }

  if count := countPODRecords(t); count != 1 {
    t.Fatalf("expected 1 POD record, got %d", count)
  }
}

