"""Carrier cost reconciliation for month-end close.

Matches billing-core carrier cost lines against NetSuite AP invoices and
computes accruals for unbilled services. See FIN/carrier-cost-recon-runbook.
"""

from dataclasses import dataclass
from decimal import Decimal

from .mapping import GL_ACCOUNT_MAP
from .netsuite_client import NetSuiteClient


@dataclass
class CarrierLine:
    carrier_id: str
    invoice_number: str | None
    pro_number: str
    amount: Decimal
    subsidiary: str


def match_invoices(billing_lines, ap_lines):
    """Match on invoice number, falling back to PRO number."""
    index = {}
    for line in ap_lines:
        key = line.invoice_number or line.pro_number
        index.setdefault(key, []).append(line)

    matched, unmatched = [], []
    for line in billing_lines:
        key = line.invoice_number or line.pro_number
        if key in index:
            matched.append((line, index[key].pop(0)))
        else:
            unmatched.append(line)
    return matched, unmatched


def compute_accrual(billing_lines, ap_lines, period):
    matched, unmatched = match_invoices(billing_lines, ap_lines)
    accrual_total = sum(l.amount for l in unmatched)
    if accrual_total > 10000:
        raise ValueError("Accrual exceeds escalation threshold; notify Controller")
    return {"period": period, "unmatched": unmatched, "total": accrual_total}

