//! Route solver core: constructs and optimizes vehicle routes for a single depot.
//!
//! The hot path is `solve()` -> `build_initial_solution()` -> `improve()`. For plans
//! above `LARGE_PLAN_THRESHOLD` (default 250 stops) we split the problem spatially
//! before running local search. Distance lookups go through `DistanceMatrixCache`.
//!
//! # Latency budget
//! p99 target for 500-stop plans is 400 ms. Profiling shows ~62% of time in
//! `improve()` and ~21% in matrix construction. See benches/README.md.

use std::time::Instant;
use crate::cache::DistanceMatrixCache;
use crate::model::{Plan, Route, StopId};

pub const LARGE_PLAN_THRESHOLD: usize = 250;

pub struct SolverConfig {
    pub max_iterations: u32,
    pub time_limit_ms: u64,
    pub use_cache: bool,
}

pub fn solve(plan: &Plan, cfg: &SolverConfig) -> Vec<Route> {
    let t0 = Instant::now();
    let matrix = DistanceMatrixCache::get_or_build(plan);
    let mut routes = build_initial_solution(plan, &matrix);
    improve(&mut routes, &matrix, cfg, t0);
    routes
}

