//! Distance matrix cache backed by Redis with an in-process LRU.
//!
//! Keys are `dm:{profile}:{geohash}:{n}` where n is the stop count bucket.
//! For 500-stop plans the matrix is 250k floats; serialization uses bincode.

use redis::Commands;
use lru::LruCache;

pub struct DistanceMatrixCache {
    lru: LruCache<String, Vec<f32>>,
    redis: redis::Connection,
}

impl DistanceMatrixCache {
    pub fn get_or_build(plan: &Plan) -> Vec<f32> {
        let key = cache_key(plan);
        if let Some(m) = self.lru.get(&key) { return m.clone(); }
        if let Ok(bytes) = self.redis.get(&key) { ... }
        let m = build_matrix(plan);
        ...
    }
}

//! Spatial splitting for large plans.
//!
//! When a plan exceeds LARGE_PLAN_THRESHOLD we partition stops into clusters
//! with a k-means pass over lat/lon, then solve each cluster independently and
//! stitch routes at the depot. This keeps the local-search neighborhood small.
//!
//! Trade-off: splitting can add 1-3% to total distance but cuts p99 by ~40%.

use crate::model::Plan;

pub struct SplitConfig {
    pub max_cluster_size: usize,
    pub min_clusters: usize,
}

pub fn split_plan(plan: &Plan, cfg: &SplitConfig) -> Vec<Plan> {
    let centroids = kmeans_centroids(plan, cfg.min_clusters);
    assign_stops(plan, &centroids)
        .into_iter()
        .map(|stops| Plan { stops, ..plan.clone() })
        .collect()
}

use criterion::{criterion_group, criterion_main, Criterion, BenchmarkId};
use routing_engine::solver::{solve, SolverConfig};
use routing_engine::fixtures::load_plan;

fn bench_solve(c: &mut Criterion) {
    let mut group = c.benchmark_group("solve");
    for size in [50, 250, 500] {
        let plan = load_plan(size);
        let cfg = SolverConfig { max_iterations: 10_000, time_limit_ms: 5_000, use_cache: true };
        group.bench_with_input(BenchmarkId::from_parameter(size), &plan, |b, p| {
            b.iter(|| solve(p, &cfg))
        });
    }
    group.finish();
}

criterion_group!(benches, bench_solve);
criterion_main!(benches);

//! Nearest-neighbor initial solution.
//!
//! Greedy construction: start at depot, repeatedly append the closest unvisited
//! stop that fits the vehicle's capacity and time window. Runs in O(n²) with
//! matrix lookups. Used as the seed for local search; quality is secondary to
//! speed here.

use crate::model::{Plan, Route, StopId};

pub fn build_initial_solution(plan: &Plan, matrix: &[f32]) -> Vec<Route> {
    let mut unvisited: Vec<StopId> = plan.stops.iter().map(|s| s.id).collect();
    let mut routes = Vec::new();
    while !unvisited.is_empty() {
        let mut route = Route::new(plan.vehicles[routes.len() % plan.vehicles.len()]);
        let mut current = plan.depot;
        while let Some(next) = closest_fitting(&current, &unvisited, matrix, &route) {
            route.push(next);
            unvisited.retain(|id| *id != next);
            current = next;
        }
        routes.push(route);
    }
    routes
}

