import Foundation
import AuthenticationServices

/// Migrates a driver from the legacy session cookie to OIDC without
/// forcing a logout. Runs once per install; guarded by a UserDefaults flag.
final class SessionMigrator {
    private let keychain: KeychainStore
    private let oidc: OIDCClient
    private static let doneKey = "auth.migrated.v1"

    init(keychain: KeychainStore, oidc: OIDCClient) {
        self.keychain = keychain
        self.oidc = oidc
    }

    func migrateIfNeeded(completion: @escaping (Result<Void, Error>) -> Void) {
        if UserDefaults.standard.bool(forKey: Self.doneKey) {
            return completion(.success(()))
        }
        guard keychain.legacySessionCookie() != nil else {
            // Fresh install: nothing to migrate, just start clean.
            UserDefaults.standard.set(true, forKey: Self.doneKey)
            return completion(.success(()))
        }
        // Exchange the legacy cookie for a refresh token exactly once.
        oidc.silentEnroll { result in
            switch result {
            case .success:
                self.keychain.deleteLegacySessionCookie()
                UserDefaults.standard.set(true, forKey: Self.doneKey)
            case .failure(let error):
                // Keep the cookie; retry on next foreground.
                return completion(.failure(error))
            }
            completion(.success(()))
        }
    }
}

