"""Invoice domain model for billing-core.

NOTE: This module is being rewritten as part of the invoicing v2 initiative.
The nightly-batch code path (build_invoice_from_shipments) is legacy and will
be deleted in phase 4. New code should use InvoiceAccrual / InvoiceBuilder.
"""

from __future__ import annotations

import datetime as dt
from dataclasses import dataclass, field
from decimal import Decimal
from enum import Enum
from typing import Iterable, Optional


class InvoiceStatus(str, Enum):
    DRAFT = "draft"
    OPEN = "open"
    PAID = "paid"
    VOID = "void"


class LineItemKind(str, Enum):
    FREIGHT = "freight"
    FUEL_SURCHARGE = "fuel_surcharge"
    CARRIER_SURCHARGE = "carrier_surcharge"
    ACCESSORIAL = "accessorial"
    TAX = "tax"
    CREDIT = "credit"


@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str  # ISO 4217, uppercase

    def __post_init__(self) -> None:
        if self.currency != self.currency.upper() or len(self.currency) != 3:
            raise ValueError(f"bad currency code: {self.currency!r}")


@dataclass
class LineItem:
    kind: LineItemKind
    description: str
    amount: Money
    quantity: Decimal = Decimal("1")
    source_event_id: Optional[str] = None
    shipment_id: Optional[str] = None

    @property
    def total(self) -> Money:
        return Money(self.amount.amount * self.quantity, self.amount.currency)


@dataclass
class Invoice:
    account_id: str
    period_id: str
    currency: str
    status: InvoiceStatus = InvoiceStatus.DRAFT
    issued_at: Optional[dt.datetime] = None
    line_items: list[LineItem] = field(default_factory=list)

    def add(self, item: LineItem) -> None:
        if item.amount.currency != self.currency:
            raise ValueError(
                f"line item currency {item.amount.currency} != invoice currency {self.currency}"
            )
        self.line_items.append(item)

    @property
    def subtotal(self) -> Money:
        total = sum((i.total.amount for i in self.line_items), Decimal("0"))
        return Money(total, self.currency)


def build_invoice_from_shipments(account_id: str, day: dt.date, shipments: Iterable[dict]) -> Invoice:
    """LEGACY nightly-batch path. Do not extend."""
    raise NotImplementedError("replaced by InvoiceBuilder in billing/accrual.py")

