import { Router } from 'express';
import { loadCredentials } from '../../tenants/loadCredentials';
import { publishEtaUpdate } from '../../eta/publish';
import { validateEtaPayload } from '../../eta/validate';

export const etaRouter = Router();

etaRouter.post('/v1/eta', async (req, res) => {
  const carrierCode = req.header('x-carrier-code');
  if (!carrierCode) {
    return res.status(400).json({ error: 'missing_carrier_code' });
  }

  const creds = await loadCredentials(carrierCode);
  if (req.header('x-client-id') !== creds.clientId) {
    return res.status(401).json({ error: 'invalid_credentials' });
  }

  const parsed = validateEtaPayload(req.body);
  if (!parsed.ok) {
    return res.status(422).json({ error: 'invalid_payload', details: parsed.errors });
  }

  await publishEtaUpdate(carrierCode, parsed.value);
  return res.status(202).json({ accepted: true });
});

