# dock_scheduler/src/constraints.py

"""Hard and soft constraints for dock-door scheduling."""

from dataclasses import dataclass
from datetime import datetime, timedelta

@dataclass(frozen=True)
class Door:
    door_id: str
    site_code: str
    door_type: str  # "dry", "reefer", "ramp"
    active: bool = True

@dataclass(frozen=True)
class Appointment:
    shipment_id: str
    site_code: str
    start: datetime
    end: datetime
    temp_controlled: bool
    door_type_required: str

def hard_constraints_ok(appt: Appointment, door: Door, roster: dict) -> bool:
    if not door.active:
        return False
    if appt.site_code != door.site_code:
        return False
    if appt.door_type_required != door.door_type:
        return False
    if roster.get("forklift_certified", 0) < 1:
        return False
    return True

def overlaps(a: Appointment, b: Appointment) -> bool:
    return a.start < b.end and b.start < a.end

